/// The start function of a TypeScript entry, when TypeScript is built.
macro_rules! entry {
    ($start:ident) => {{
        #[cfg(feature = "lang-typescript")]
        let start: Option<fn(&mut crate::arena::Arena, u32) -> u32> =
            Some(crate::typescript::$start);
        #[cfg(not(feature = "lang-typescript"))]
        let start = None;
        start
    }};
}

